from pathlib import Path
import re

root=Path('.')
auto_path=root/'src/automation.ts'
admin_path=root/'src/admin.ts'
auto=auto_path.read_text()
admin=admin_path.read_text()

# 1. Expor o motor real da automação e registrar quantos candidatos existem em cada faixa.
if 'export async function searchOffersForRule(' not in auto:
    auto=auto.replace('async function searchOffers(\n','export async function searchOffersForRule(\n',1)
auto=auto.replace('} = await searchOffers(db, env, rule, candidateTarget, excludeOffer, slot);','} = await searchOffersForRule(db, env, rule, candidateTarget, excludeOffer, slot);')

if 'commissionAttemptStats' not in auto:
    auto=auto.replace('  let commissionAttempts: number[] = [];\n','''  let commissionAttempts: number[] = [];\n  const commissionAttemptStats: Array<{ threshold: number; eligible: number }> = [];\n  const recordCommissionAttempt = (threshold: number, eligible: number) => {\n    const existing = commissionAttemptStats.find((item) => item.threshold === threshold);\n    if (existing) existing.eligible = Math.max(existing.eligible, eligible);\n    else commissionAttemptStats.push({ threshold, eligible });\n  };\n''',1)
    auto=auto.replace('''      commissionAttempts.push(threshold);\n      const candidates = snapshots.filter((offer) => Math.max(0, Number(offer.commissionPercent) || 0) >= threshold);\n      addUnique(candidates);''','''      commissionAttempts.push(threshold);\n      const candidates = snapshots.filter((offer) => Math.max(0, Number(offer.commissionPercent) || 0) >= threshold);\n      recordCommissionAttempt(threshold, candidates.length);\n      addUnique(candidates);''',1)
    auto=auto.replace('''      if (!commissionAttempts.includes(plan.desired)) commissionAttempts.push(plan.desired);\n      addUnique(primary.selected);''','''      if (!commissionAttempts.includes(plan.desired)) commissionAttempts.push(plan.desired);\n      recordCommissionAttempt(plan.desired, primary.selected.length);\n      addUnique(primary.selected);''',1)
    auto=auto.replace('''        for (const threshold of plan.thresholds.slice(1)) {\n          if (!commissionAttempts.includes(threshold)) commissionAttempts.push(threshold);\n          const before = selected.length;\n          addUnique(ranked.filter((offer) => Math.max(0, Number(offer.commissionPercent) || 0) >= threshold));''','''        for (const threshold of plan.thresholds.slice(1)) {\n          if (!commissionAttempts.includes(threshold)) commissionAttempts.push(threshold);\n          const thresholdCandidates = ranked.filter((offer) => Math.max(0, Number(offer.commissionPercent) || 0) >= threshold);\n          recordCommissionAttempt(threshold, thresholdCandidates.length);\n          const before = selected.length;\n          addUnique(thresholdCandidates);''',1)
    auto=auto.replace('''    commissionResolved: resolvedCommission,\n    commissionAttempts,\n  };''','''    commissionResolved: resolvedCommission,\n    commissionAttempts,\n    commissionAttemptStats,\n  };''',1)

# 2. Admin usa o mesmo motor e não mantém uma segunda implementação da flexibilização.
admin=admin.replace('import { createShopeeProvider } from "../lib/affiliate/shopee/adapter";\n','')
admin=admin.replace('import { searchQualifiedOffers } from "../lib/search-engine";\n','')
admin=admin.replace('import { commissionPlan } from "./rule-policy";\n','')
admin=admin.replace('import { runRuleNow, workerTick } from "./automation";','import { runRuleNow, searchOffersForRule, workerTick } from "./automation";')

pattern=re.compile(r'async function preview\(request: Request, env: Env\) \{.*?\n\}\n\nexport async function handleAdminApi',re.S)
new_preview='''async function preview(request: Request, env: Env) {\n  const body=await request.json().catch(()=>({})) as JsonObject;\n  const settings=(body.settings&&typeof body.settings==="object"&&!Array.isArray(body.settings)?body.settings:{}) as JsonObject;\n  const minCommission=nullableNumber(body.minCommission??body.min_commission,0,100)??undefined;\n  const minDiscount=nullableNumber(body.minDiscount??body.min_discount,0,100)??undefined;\n  const maxPrice=nullableNumber(body.maxPrice??body.max_price,0,1_000_000)??undefined;\n  const quantityRaw=Number(body.quantity||1);\n  const quantity=Number.isInteger(quantityRaw)?Math.min(Math.max(quantityRaw,1),20):1;\n  const requestedSort=["commission","price","sales","discount"].includes(String(body.sort))?String(body.sort) as AutomationRuleRow["sort"]:null;\n  const timezone=text(body.timezone,80)||"America/Sao_Paulo";\n  const previewRule:AutomationRuleRow={id:"preview",name:"Prévia",enabled:false,networks:["shopee"],channels:["telegram"],keyword:"",category:null,min_commission:minCommission??null,min_discount:minDiscount??null,max_price:maxPrice??null,quantity,sort:requestedSort,avoid_repeat_days:0,schedule_cron:null,timezone,dry_run:true,settings:{...settings,searchScope:"all"}};\n  const result=await searchOffersForRule(new SupabaseRest(env),env,previewRule,quantity,undefined,new Date());\n  const template=validTemplate(settings.contentTemplate);\n  const thread=Number(settings.telegramThreadId);\n  const messageThreadId=Number.isInteger(thread)&&thread>0?thread:undefined;\n  const flexEnabled=Boolean(settings.flexCommissionEnabled)&&Number(result.commissionTarget)>0;\n  const attempts=(result.commissionAttemptStats||[]).map((item)=>({threshold:item.threshold,eligible:item.eligible}));\n  const diagnostics={scanned:result.scanned,rejectedRelevance:0,invalidMetrics:0,belowCommission:0,belowDiscount:0,aboveMaxPrice:0,equivalentDuplicates:0,excludedRecent:result.excluded,eligible:result.selected.length,zeroSalesAccepted:result.selected.filter((offer)=>Number(offer.sourceMetadata?.sales)===0).length,zeroRatingAccepted:result.selected.filter((offer)=>Number(offer.sourceMetadata?.rating)===0).length};\n  const suggestions:string[]=[];\n  if(result.selected.length===0){\n    if(flexEnabled){suggestions.push(`A busca real percorreu a meta de ${result.commissionTarget}% até o piso de ${Number(settings.flexCommissionFloor)||result.commissionTarget}% sem encontrar uma oferta que também cumpra desconto, preço e fonte selecionados.`);if(minDiscount!=null)suggestions.push(`O desconto mínimo de ${minDiscount}% continua obrigatório em todas as faixas de comissão.`);}\n    else{if(minCommission!=null)suggestions.push(`A comissão está rígida em ${minCommission}%. Ative a flexibilização para permitir faixas menores.`);if(minDiscount!=null)suggestions.push(`Revise o desconto mínimo de ${minDiscount}% se quiser ampliar a busca.`);}\n  }\n  return json({dryRun:true,selected:result.selected.length,scanned:result.scanned,pages:result.pages,diagnostics,filters:{minCommission:minCommission??null,minDiscount:minDiscount??null,maxPrice:maxPrice??null},suggestions,commissionFlex:{enabled:flexEnabled,target:result.commissionTarget,floor:Number(settings.flexCommissionFloor)||result.commissionTarget,step:Number(settings.flexCommissionStep)||5,resolved:result.commissionResolved,attempts},selectionEngine:"automation",sourceMode:result.sourceMode,sourceNiche:result.sourceNiche,strategy:{scope:result.sourceMode,requests:result.pages,queries:result.sourceNiche?[result.sourceNiche]:["Todos os produtos"],sourceSorts:[requestedSort||"relevance"]},publications:result.selected.map((offer)=>({offer,content:generateContent(offer,"telegram",{template,messageThreadId})}))});\n}\n\nexport async function handleAdminApi'''
admin,count=pattern.subn(new_preview,admin,count=1)
if count!=1: raise SystemExit(f'preview replacement count={count}')

# 3. A prévia lê exatamente o mesmo estado do formulário que será salvo.
payload_pattern=re.compile(r"\s*var targetCommission=Number\(byId\('minCommission'\).*?var payload=\{keyword:'',quantity:1,minCommission:byId\('minCommission'\).*?settings:settings\};",re.S)
admin,count=payload_pattern.subn("\n      var payload=typeof window.readAutomationDraftFromForm==='function'?window.readAutomationDraftFromForm():{keyword:'',quantity:1,minCommission:byId('minCommission')&&byId('minCommission').value,minDiscount:byId('minDiscount')&&byId('minDiscount').value,maxPrice:byId('maxPrice')&&byId('maxPrice').value,sort:byId('sort')&&byId('sort').value,settings:{contentTemplate:(byId('contentTemplate')&&byId('contentTemplate').value)||'offer',telegramThreadId:currentThread(),telegramTopicName:currentTopicName()}};",admin,count=1)
if count!=1: raise SystemExit(f'preview payload replacement count={count}')

marker='function collectSmartSettings(body){'
pos=admin.find(marker)
if pos<0: raise SystemExit('collectSmartSettings not found')
if 'window.readAutomationDraftFromForm=readAutomationDraftFromForm;' not in admin:
    fn="""function readAutomationDraftFromForm(){var val=function(id){var e=document.getElementById(id);return e?e.value:''},num=function(id){var v=val(id);return v===''?null:Number(v)},list=document.getElementById('sourceList');var settings={contentTemplate:val('contentTemplate')||'offer',intervalMinutes:Number(val('intervalMinutes'))||60,windowStart:val('windowStart')||'09:00',windowEnd:val('windowEnd')||'22:00',telegramThreadId:currentThread(),telegramTopicName:currentThread()?currentTopicName():null,listId:list&&list.value||null,listName:list&&list.selectedIndex>0?list.options[list.selectedIndex].text.split(' · ')[0]:null};var body={min_commission:num('minCommission'),min_discount:num('minDiscount'),max_price:num('maxPrice'),sort:val('sort')||null,quantity:1,timezone:val('timezone')||'America/Sao_Paulo',settings:settings};collectSmartSettings(body);return{keyword:'',quantity:1,minCommission:body.min_commission,minDiscount:body.min_discount,maxPrice:body.max_price,sort:body.sort,timezone:body.timezone,settings:body.settings};}\nwindow.readAutomationDraftFromForm=readAutomationDraftFromForm;\n"""
    admin=admin[:pos]+fn+admin[pos:]

# 4. Se houver oferta, ainda mostrar a escada e a faixa escolhida.
old_success="card.innerHTML='<div class=\"live-preview-grid\">'+img+'<div class=\"live-preview-message\">'+esc(msg)+'</div></div>'+previewDiagnosticSummary(res);"
if old_success in admin:
    new_success="var flex=res&&res.commissionFlex,flexBanner='';if(flex&&flex.enabled){flexBanner='<div class=\"commission-flex-preview\" style=\"margin-top:10px\"><div class=\"commission-flex-title\"><b>🧠 Comissão inteligente ATIVA</b><span>Meta '+esc(flex.target)+'% · usada '+esc(flex.resolved==null?'—':flex.resolved+'%')+'</span></div><div class=\"commission-flex-steps\">';(flex.attempts||[]).forEach(function(a){flexBanner+='<span class=\"commission-flex-step '+(flex.resolved===a.threshold?'hit':'')+'\">≥ '+esc(a.threshold)+'% <b>'+esc(a.eligible)+'</b></span>'});flexBanner+='</div><div class=\"diag-note\">Prévia e automação real usam o mesmo motor de seleção.</div></div>';}card.innerHTML='<div class=\"live-preview-grid\">'+img+'<div class=\"live-preview-message\">'+esc(msg)+'</div></div>'+flexBanner+previewDiagnosticSummary(res);"
    admin=admin.replace(old_success,new_success,1)

auto_path.write_text(auto)
admin_path.write_text(admin)
print('patched unified preview v3')
